package ecommerce_payment_service.workers;

import java.nio.charset.StandardCharsets;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.amqp.core.Message;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.stereotype.Component;

/**
 * RabbitMQ (spring-amqp) worker loop for payment-service. Hosted by the {@code
 * --datrix.run=job-runner} process.
 *
 * <p>Auto-generated by datrix-codegen-java. Do not edit manually.
 */
@Component
public class PaymentServiceQueueWorker {

  private static final Logger logger = LoggerFactory.getLogger(PaymentServiceQueueWorker.class);
  private static final long RECEIVE_TIMEOUT_MS = 1000L;

  private final RabbitTemplate rabbitTemplate;
  private final PaymentServiceQueueHandlers handlers;
  private volatile boolean running;

  public PaymentServiceQueueWorker(
      RabbitTemplate rabbitTemplate, PaymentServiceQueueHandlers handlers) {
    this.rabbitTemplate = rabbitTemplate;
    this.handlers = handlers;
  }

  private void dispatch(String physicalQueueName, String body) throws Exception {
    switch (physicalQueueName) {
      case "order-service.process-payment" -> handlers.handleProcessPayment(body);
      case "order-service.settle-payment" -> handlers.handleSettlePayment(body);
      default -> logger.warn("unknown_queue physicalQueueName={}", physicalQueueName);
    }
  }

  private void pollOnce(String physicalQueueName) {
    Message message = rabbitTemplate.receive(physicalQueueName, RECEIVE_TIMEOUT_MS);
    if (message == null) {
      return;
    }
    try {
      dispatch(physicalQueueName, new String(message.getBody(), StandardCharsets.UTF_8));
    } catch (Exception e) {
      logger.error("task_failed queue={}", physicalQueueName, e);
    }
  }

  /** Start the blocking poll loop -- runs until {@link #stop()} is called. */
  public void start() {
    logger.info("queue_worker_starting service=payment-service engine=rabbitmq");
    running = true;
    while (running) {
      pollOnce("order-service.process-payment");
      pollOnce("order-service.settle-payment");
    }
    logger.info("queue_worker_stopped service=payment-service");
  }

  /** Signal the poll loop to stop after its current pass. */
  public void stop() {
    running = false;
  }
}
